/**
 * Removes em-dash ("—") usage from step_title_{lang} / instruction_{lang} /
 * notes_{lang} cells in the procedure_steps tab, restructuring each language's
 * existing sentence independently (no re-translation from English) using
 * natural clause connectors (colon, semicolon, comma, parenthetical, or a
 * sentence split) appropriate to that language's grammar and to the specific
 * rhetorical role the dash was playing (definition/enumeration vs. reason
 * clause vs. appositive).
 *
 * Scope: procedure_steps tab only (per parallel-agent ownership split with
 * other in-flight content-cleanup agents working other tabs).
 *
 * Rows are matched by parent_slug + step_number (not raw sheet row number,
 * which is fragile against upstream row insertions/deletions). Only the
 * specific {field}_{lang} cell for a match is ever touched; recite_shloka_slug,
 * recite_stanza_range, and every other column are never read or written.
 *
 * Safety: for every fix, the script re-fetches the tab fresh and requires the
 * live cell text to exactly equal the recorded NEW_TEXT key's counterpart
 * "old" (reconstructed by re-inserting an em dash is NOT how this works --
 * instead each fix is verified two ways: (1) the live cell must still contain
 * "—", and (2) the live cell, read fresh, is what gets diffed and shown; nothing
 * is written unless --write is passed AND the live cell still contains "—".
 * This protects against writing over content someone else already touched.
 *
 * PHASE 1 (this run): DRY RUN ONLY. Do not pass --write.
 * PHASE 2 (later, after human review): re-run with --write to apply.
 *
 * Run: node scripts/fix-em-dash-procedure-steps.mjs          (dry run)
 *      node scripts/fix-em-dash-procedure-steps.mjs --write  (apply -- Phase 2 only)
 */
import { getSheetsClient, SPREADSHEET_ID, parseWriteFlag, colLetter, getTabWithHeaders } from './lib-sheets.mjs';

